def test_f2_direct_one_byte_and_counted_zero():
    assert cap_base64_images(ONE_BYTE, 0, A) == "[image-redacted]"
    assert _cap_base64_images_counted(ONE_BYTE, 0, A) == ("[image-redacted]", 1)
    assert cap_base64_images("QQ==", 0, A, True) == "[image-redacted]"
    assert cap_base64_images("QQ==", 0, A, False) == "QQ=="
    assert cap_base64_images("", 0, A, True) == ""
    original = [ONE_BYTE, "ordinary"]
    assert cap_base64_images(original, 0, A) == ["[image-redacted]", "ordinary"]
    assert original == [ONE_BYTE, "ordinary"]
    assert cap_base64_images(tuple(original), 0, A) == ("[image-redacted]", "ordinary")


@pytest.mark.parametrize("maximum", [0, "0", -1, float("nan"), "abc", True, False, 1.5, float("inf"), None])
def test_f2_direct_invalid_caps_fail_closed(maximum, caplog):
    assert cap_base64_images(ONE_BYTE, maximum, A) == "[image-redacted]"
    if maximum not in (0, "0") or isinstance(maximum, bool):
        assert [r.getMessage() for r in caplog.records] == ["Invalid base64 image cap; using 0."]
    else:
        assert not caplog.records


@pytest.mark.parametrize("source", ["default", "init", "env"])
@pytest.mark.parametrize("value", [0, "0", -1, float("nan"), "abc", True, False, 1.5, float("inf")])
def test_f2_config_default_init_env_and_export_routes(monkeypatch, caplog, source, value):
    from fi_instrumentation.instrumentation.config import TraceConfig, DEFAULT_BASE64_IMAGE_MAX_LENGTH
    monkeypatch.delenv("FI_BASE64_IMAGE_MAX_LENGTH", raising=False)
    kwargs = {}
    if source == "init":
        monkeypatch.setenv("FI_BASE64_IMAGE_MAX_LENGTH", "90000")
        kwargs["base64_image_max_length"] = value
    elif source == "env":
        monkeypatch.setenv("FI_BASE64_IMAGE_MAX_LENGTH", str(value))
    config = TraceConfig(**kwargs)
    assert DEFAULT_BASE64_IMAGE_MAX_LENGTH == 0
    assert config.base64_image_max_length == 0
    assert config.redact_value(ONE_BYTE) == "[image-redacted]"
    assert config.mask("arbitrary.retained", ONE_BYTE) == "[image-redacted]"
    assert config.mask("arbitrary.lazy", lambda: ONE_BYTE) == "[image-redacted]"
    assert config.mask("gen_ai.input.messages.0.message_content.image", "QQ==") == "[image-redacted]"
    if source != "default" and (value not in (0, "0") or isinstance(value, bool)):
        assert [r.getMessage() for r in caplog.records] == ["Invalid base64 image cap; using 0."]
    else:
        assert not caplog.records


def test_f2_positive_user_cap_and_precedence_are_unchanged(monkeypatch):
    from fi_instrumentation.instrumentation.config import TraceConfig
    monkeypatch.setenv("FI_BASE64_IMAGE_MAX_LENGTH", "0")
    for maximum in (len(ONE_BYTE), len(ONE_BYTE) + 1, 32000):
        config = TraceConfig(base64_image_max_length=maximum)
        assert config.base64_image_max_length == maximum
        assert config.redact_value(ONE_BYTE) == ONE_BYTE
        assert cap_base64_images(ONE_BYTE, maximum, A) == ONE_BYTE
    assert cap_base64_images(ONE_BYTE, len(ONE_BYTE) - 1, A) == "__REDACTED__"
    assert cap_base64_images("before " + ONE_BYTE + " after", 1, A) == "[image-redacted]"
    monkeypatch.setenv("FI_BASE64_IMAGE_MAX_LENGTH", "32000")
    assert TraceConfig().redact_value(ONE_BYTE) == ONE_BYTE
    assert TraceConfig(base64_image_max_length=0).redact_value(ONE_BYTE) == "[image-redacted]"
    # The r4c7 base includes R-WS/R-TD; preserve its positive-cap whole-scope outputs.
    whitespace = "data:image/png;base64," + " ".join(["QUJD"] * 40)
    delimiter = "data:image/png;name=" + "q" * 1024 + ";base64%2C" + "QUJD" * 40
    assert cap_base64_images(whitespace, 64, A) == "[image-redacted]"
    assert cap_base64_images(delimiter, 64, A) == "[image-redacted]"
    assert cap_base64_images(whitespace, 0, A) == "[image-redacted]"
    assert cap_base64_images(delimiter, 0, A) == "[image-redacted]"


def test_f2_core_real_export_surfaces(monkeypatch):
    from fi_instrumentation.instrumentation._tracers import FITracer
    from fi_instrumentation.instrumentation.config import TraceConfig
    from opentelemetry.sdk.trace import TracerProvider
    from opentelemetry.sdk.trace.export import SimpleSpanProcessor
    from opentelemetry.sdk.trace.export.in_memory_span_exporter import InMemorySpanExporter
    from opentelemetry.trace import Link, SpanContext, Status, StatusCode, TraceFlags
    monkeypatch.delenv("FI_BASE64_IMAGE_MAX_LENGTH", raising=False)
    exporter = InMemorySpanExporter()
    provider = TracerProvider()
    provider.add_span_processor(SimpleSpanProcessor(exporter))
    config = TraceConfig(pii_redaction=False, hide_error_details=False)
    tracer = FITracer(provider.get_tracer(__name__), config=config)
    context = SpanContext(trace_id=1, span_id=2, is_remote=True, trace_flags=TraceFlags(1))
    caller = {"creation": ONE_BYTE}
    error = ValueError(ONE_BYTE)
    try:
        span = tracer.start_span("f2", attributes=caller, links=[Link(context, {"link": ONE_BYTE})])
        span.set_attribute("setter", ONE_BYTE)
        span.set_attributes({"bulk": ONE_BYTE})
        span.add_event("f2", {"event": ONE_BYTE})
        span.record_exception(error)
        span.set_status(Status(StatusCode.ERROR, ONE_BYTE))
        span.end()
        result, = exporter.get_finished_spans()
        assert result.attributes["creation"] == "[image-redacted]"
        assert result.attributes["setter"] == "[image-redacted]"
        assert result.attributes["bulk"] == "[image-redacted]"
        assert result.links[0].attributes["link"] == "[image-redacted]"
        event, = [e for e in result.events if e.name == "f2"]
        assert event.attributes["event"] == "[image-redacted]"
        exception, = [e for e in result.events if e.name == "exception"]
        assert exception.attributes["exception.message"] == "[image-redacted]"
        assert exception.attributes["exception.stacktrace"] == "[image-redacted]"
        assert exception.attributes["exception.type"] == "ValueError"
        assert result.status.description == "[image-redacted]"
        assert result.status.status_code == StatusCode.ERROR
        assert caller == {"creation": ONE_BYTE}
        assert error.args == (ONE_BYTE,)
    finally:
        provider.shutdown()








def test_f2_q1_nested_declared_and_structural_controls():
    for depth in (1, 7, 9, 15):
        raw, expected = ONE_BYTE, "[image-redacted]"
        for _ in range(depth):
            raw, expected = json.dumps(raw), json.dumps(expected)
        assert cap_base64_images(raw, 0, A) == expected
    raw = '{"type":"image","source":{"data":"QQ=="},"name":"QQ==","keep":1}'
    assert cap_base64_images(raw, 0, A) == '{"type":"image","source":{"data":"[image-redacted]"},"name":"QQ==","keep":1}'
    nonconvergent = "ordinary %25252541"
    assert cap_base64_images(nonconvergent, 0, A) == "[image-redacted]"
    assert cap_base64_images("ordinary %252541", 0, A) == "ordinary %252541"
    value = '"x"'
    expected = '"[image-redacted]"'
    for _ in range(16):
        value = json.dumps(value)
    for _ in range(15):
        expected = json.dumps(expected)
    assert cap_base64_images(value, 0, A) == expected
    value = ONE_BYTE
    expected = "[image-redacted]"
    for _ in range(16):
        value = json.dumps(value)
        expected = json.dumps(expected)
    assert cap_base64_images(value, 0, A) == expected


