def test_f2_r2_comma_trigger_literal_controls():
    # Split-token pair: neither token holds data:, image/ and a comma in order.
    for split in ('["data:image/png;name=", ";base64,QUJD"]', '{"data:image/png;name=":";base64,QUJD"}'):
        assert cap_base64_images(split, 0, A) == split
        assert _cap_base64_images_counted(split, 0, A) == (split, 0)
    # Empty payload with the comma: redacted as one whole scope.
    assert cap_base64_images("data:image/png;base64,", 0, A) == "[image-redacted]"
    assert _cap_base64_images_counted("data:image/png;base64,", 0, A) == ("[image-redacted]", 1)
    assert cap_base64_images('{"x":"data:image/png;base64,","keep":1}', 0, A) == '{"x":"[image-redacted]","keep":1}'
    # Mentions without a following comma, or in the wrong order, are preserved.
    for mention in ("data:image/png", "data:image/png;base64", "data:image/", "image/png, data:",
                    ", data:image/png", "data: arbitrary image/png", '{"x":"data:image/png","keep":1}'):
        assert cap_base64_images(mention, 0, A) == mention
        assert _cap_base64_images_counted(mention, 0, A) == (mention, 0)
    # Any later comma in the same scope view triggers, including a decoded one.
    assert cap_base64_images("data: arbitrary image/png, ignored", 0, A) == "[image-redacted]"
    assert cap_base64_images("data:image/png;base64%2CQUJD", 0, A) == "[image-redacted]"
    # Positive caps keep the r4c7 recognizer.
    assert cap_base64_images("data:image/png;base64,QUJD", 64, A) == "data:image/png;base64,QUJD"
    assert cap_base64_images("data:image/png;base64,", 64, A) == "data:image/png;base64,"


