@pytest.mark.parametrize("case_id,value,expected", R2_COMMA_CASES, ids=[c[0] for c in R2_COMMA_CASES])
def test_f2_r2_comma_completes_the_trigger(case_id, value, expected):
    assert cap_base64_images(value, 0, A) == expected, case_id
    assert cap_base64_images(value[:-5], 0, A) == value[:-5], case_id
    assert value.endswith(",QUJD")
